(* [comment removed for export] *)
Definition trace_cells (M : word -> option byte) (this sz : Z) : Prop :=
  forall i, 0 <= i < sz -> exists w : word, cellA M (this + 16 + 8 * i) 8 (bv_unsigned w).

Lemma Z_land_upper_7 : forall a, 0 <= a -> Z.land a 7 <= 7.
Proof.
